def glomit(self, target, scope):
    if isinstance(target, dict):
        result = type(target)()
        for key, val in target.items():
            # Apply fill_spec to each value; if fill_spec is a literal, 
            # use it directly rather than trying to evaluate it as a spec
            if isinstance(self.fill_spec, (dict, list, tuple, str)):
                result[key] = scope[glom](val, self.fill_spec, scope)
            else:
                result[key] = self.fill_spec
        return result
    # For non-dict targets, return target unchanged if fill_spec is a literal
    if not isinstance(self.fill_spec, (dict, list, tuple, str)):
        return target
    return scope[glom](target, self.fill_spec, scope)
